private readonly ConcurrentDictionary<string, Task<User?>> _inflight = new();

public async Task<User?> GetUserAsync(string id, CancellationToken ct)
{
    var cached = await _redis.GetAsync<User>("user:" + id, ct);
    if (cached is not null) return cached;

    var task = _inflight.GetOrAdd(id, static (key, self) => self.LoadAndCacheAsync(key), this);
    try { return await task; }
    finally { _inflight.TryRemove(id, out _); }
}

private readonly SemaphoreSlim _dbGate = new(32);

private async Task<User?> LoadAndCacheAsync(string id)
{
    await _dbGate.WaitAsync();
    try
    {
        var user = await _db.Users.FindAsync(id);
        await _redis.SetAsync("user:" + id, user, TimeSpan.FromMinutes(5));
        return user;
    }
    finally { _dbGate.Release(); }
}

